import sys,time
INF=100000000
MATE=100000
VALUE={'p':100,'n':320,'b':330,'r':500,'q':900,'k':20000}
PROMO='nbrq'

def attacked(b,sq,by):
    if sq<0 or sq>=64:return False
    r,f=divmod(sq,8)
    rr=r-1 if by==0 else r+1
    pawn='P' if by==0 else 'p'
    if 0<=rr<8:
        for ff in (f-1,f+1):
            if 0<=ff<8 and b[rr*8+ff]==pawn:return True
    knight='N' if by==0 else 'n'
    for dr,df in ((2,1),(2,-1),(-2,1),(-2,-1),(1,2),(1,-2),(-1,2),(-1,-2)):
        x,y=r+dr,f+df
        if 0<=x<8 and 0<=y<8 and b[x*8+y]==knight:return True
    king='K' if by==0 else 'k'
    for dr in (-1,0,1):
        for df in (-1,0,1):
            if dr or df:
                x,y=r+dr,f+df
                if 0<=x<8 and 0<=y<8 and b[x*8+y]==king:return True
    for dr,df,types in ((1,0,'rq'),(-1,0,'rq'),(0,1,'rq'),(0,-1,'rq'),(1,1,'bq'),(1,-1,'bq'),(-1,1,'bq'),(-1,-1,'bq')):
        x,y=r+dr,f+df
        while 0<=x<8 and 0<=y<8:
            xpc=b[x*8+y]
            if xpc!='.':
                if xpc.isupper()==(by==0) and xpc.lower() in types:return True
                break
            x+=dr;y+=df
    return False

def king_square(p,side):
    k='K' if side==0 else 'k'
    for i,x in enumerate(p.b):
        if x==k:return i
    return -1

class Position:
    def __init__(self,b,side,rights,ep,half,full):
        self.b=tuple(b);self.side=side;self.rights=rights;self.ep=ep;self.half=half;self.full=full
    @classmethod
    def fen(cls,text):
        a=text.split()
        if len(a)<6:raise ValueError
        b=['.']*64
        for ri,row in enumerate(a[0].split('/')):
            s=(7-ri)*8
            for ch in row:
                if ch.isdigit():s+=int(ch)
                else:b[s]=ch;s+=1
        rights=0
        for i,ch in enumerate('KQkq'):
            if ch in a[2]:rights|=1<<i
        ep=-1
        if a[3]!='-':ep=ord(a[3][0])-97+8*(int(a[3][1])-1)
        return cls(b,0 if a[1]=='w' else 1,rights,ep,int(a[4]),int(a[5]))
    @classmethod
    def start(cls):
        return cls.fen('rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1')

def encode(a,z,promo=0,flags=0):
    return a|(z<<6)|(promo<<12)|(flags<<16)

def generate(p,captures=False):
    b=p.b;white=p.side==0;out=[]
    def add(a,z,pr=0,fl=0,cap=False):
        if not captures or cap or pr:out.append(encode(a,z,pr,fl))
    for s,pc in enumerate(b):
        if pc=='.' or pc.isupper()!=white:continue
        r,f=divmod(s,8);typ=pc.lower()
        if typ=='p':
            d=8 if white else -8
            z=s+d
            if 0<=z<64 and b[z]=='.':
                pr=z//8==(7 if white else 0)
                if pr:
                    for q in (4,3,2,1):add(s,z,q)
                else:add(s,z)
                if not captures and r==(1 if white else 6) and b[s+2*d]=='.':add(s,s+2*d,0,4)
            for df in (-1,1):
                if 0<=f+df<8:
                    z=s+d+df
                    if 0<=z<64:
                        x=b[z]
                        cap=x!='.' and x.isupper()!=white and x.lower()!='k'
                        if cap:
                            if z//8==(7 if white else 0):
                                for q in (4,3,2,1):add(s,z,q,0,True)
                            else:add(s,z,0,0,True)
                        elif z==p.ep:add(s,z,0,2,True)
        elif typ=='n':
            for dr,df in ((2,1),(2,-1),(-2,1),(-2,-1),(1,2),(1,-2),(-1,2),(-1,-2)):
                x,y=r+dr,f+df
                if 0<=x<8 and 0<=y<8:
                    z=x*8+y;target=b[z]
                    cap=target!='.' and target.isupper()!=white and target.lower()!='k'
                    if target=='.' or cap:add(s,z,0,0,cap)
        elif typ in 'brq':
            dirs=[]
            if typ in 'bq':dirs += ((1,1),(1,-1),(-1,1),(-1,-1))
            if typ in 'rq':dirs += ((1,0),(-1,0),(0,1),(0,-1))
            for dr,df in dirs:
                x,y=r+dr,f+df
                while 0<=x<8 and 0<=y<8:
                    z=x*8+y;target=b[z]
                    if target=='.':add(s,z)
                    else:
                        if target.isupper()!=white and target.lower()!='k':add(s,z,0,0,True)
                        break
                    x+=dr;y+=df
        else:
            for dr in (-1,0,1):
                for df in (-1,0,1):
                    if dr or df:
                        x,y=r+dr,f+df
                        if 0<=x<8 and 0<=y<8:
                            z=x*8+y;target=b[z]
                            cap=target!='.' and target.isupper()!=white and target.lower()!='k'
                            if target=='.' or cap:add(s,z,0,0,cap)
            if not captures and s==(4 if white else 60) and not attacked(b,s,p.side^1):
                if white and p.rights&1 and b[5]==b[6]=='.' and b[7]=='R' and not attacked(b,5,1) and not attacked(b,6,1):add(s,6,0,1)
                if white and p.rights&2 and b[1]==b[2]==b[3]=='.' and b[0]=='R' and not attacked(b,3,1) and not attacked(b,2,1):add(s,2,0,1)
                if not white and p.rights&4 and b[61]==b[62]=='.' and b[63]=='r' and not attacked(b,61,0) and not attacked(b,62,0):add(s,62,0,1)
                if not white and p.rights&8 and b[57]==b[58]==b[59]=='.' and b[56]=='r' and not attacked(b,59,0) and not attacked(b,58,0):add(s,58,0,1)
    return out

def make(p,m):
    a=m&63;z=(m>>6)&63;pr=(m>>12)&15;fl=m>>16
    b=list(p.b);pc=b[a];cap=b[z];b[a]='.'
    if fl&2:
        b[z+(-8 if pc.isupper() else 8)]='.';cap='p'
    b[z]=pc
    if fl&1:
        if z==6:b[5]=b[7];b[7]='.'
        elif z==2:b[3]=b[0];b[0]='.'
        elif z==62:b[61]=b[63];b[63]='.'
        elif z==58:b[59]=b[56];b[56]='.'
    if pr:b[z]=PROMO[pr-1].upper() if pc.isupper() else PROMO[pr-1]
    rights=p.rights
    if pc=='K':rights&=12
    elif pc=='k':rights&=3
    if a==0 or z==0:rights&=~2
    if a==7 or z==7:rights&=~1
    if a==56 or z==56:rights&=~8
    if a==63 or z==63:rights&=~4
    ep=(a+z)//2 if pc.lower()=='p' and abs(z-a)==16 else -1
    half=0 if pc.lower()=='p' or cap!='.' else p.half+1
    full=p.full+(1 if p.side else 0)
    return Position(b,p.side^1,rights,ep,half,full)

def legal(p,captures=False):
    result=[];side=p.side
    for m in generate(p,captures):
        q=make(p,m);ks=king_square(q,side)
        if ks>=0 and not attacked(q.b,ks,side^1):result.append(m)
    return result

def text_move(m):
    a=m&63;z=(m>>6)&63;pr=(m>>12)&15
    s='abcdefgh'[a&7]+str(a//8+1)+'abcdefgh'[z&7]+str(z//8+1)
    return s+(PROMO[pr-1] if pr else '')

def evaluate(p):
    score=0;phase=0;wp=[0]*8;bp=[0]*8;bishops_w=0;bishops_b=0
    for pc in p.b:
        if pc!='.' and pc.lower() in 'nbrq':phase += {'n':1,'b':1,'r':2,'q':4}[pc.lower()]
    for s,pc in enumerate(p.b):
        if pc=='.':continue
        typ=pc.lower();sg=1 if pc.isupper() else -1;v=VALUE[typ]
        score+=sg*v;r,f=divmod(s,8);rank=r if sg==1 else 7-r
        center=7-abs(2*f-7)-abs(2*rank-7)
        if typ=='p':
            score+=sg*(rank*9+center*2);(wp if sg==1 else bp)[f]+=1
            enemy='p' if sg==1 else 'P';passed=True
            rr=range(r+1,8) if sg==1 else range(r-1,-1,-1)
            for r2 in rr:
                for f2 in (f-1,f,f+1):
                    if 0<=f2<8 and p.b[r2*8+f2]==enemy:passed=False
            if passed:score+=sg*(18+rank*8)
        elif typ=='n':score+=sg*(center*10-abs(rank-3)*2); 
        elif typ=='b':score+=sg*(center*5);bishops_w+=sg==1;bishops_b+=sg==-1
        elif typ=='r':score+=sg*(rank*4+(8 if f in (3,4) else 0));
        elif typ=='q':score+=sg*(center*2)
        else:score+=sg*((-center*3) if phase>10 else center*9)
    if bishops_w>=2:score+=28
    if bishops_b>=2:score-=28
    for n in wp:score-=max(0,n-1)*12
    for n in bp:score+=max(0,n-1)*12
    for f,n in enumerate(wp):
        if n and (f==0 or wp[f-1]==0) and (f==7 or wp[f+1]==0):score-=9*n
    for f,n in enumerate(bp):
        if n and (f==0 or bp[f-1]==0) and (f==7 or bp[f+1]==0):score+=9*n
    if not any(x.lower() in 'pnrq' for x in p.b) and sum(x.lower() in 'b' for x in p.b)<=1 and sum(x.lower() in 'n' for x in p.b)<=1:return 0
    return score if p.side==0 else -score

class Engine:
    def __init__(self):
        self.pos=Position.start();self.tt={};self.history={};self.killers={};self.nodes=0;self.deadline=0
    def tick(self):
        self.nodes+=1
        if self.nodes&31==0 and time.perf_counter()>=self.deadline:raise TimeoutError
    def order_score(self,p,m,ttmove,ply):
        a=m&63;z=(m>>6)&63;pr=(m>>12)&15;fl=m>>16;score=10000000 if m==ttmove else 0
        target=p.b[z]
        if fl&2:target='p'
        if target!='.':score+=1000000+VALUE[target.lower()]*10-VALUE[p.b[a].lower()]
        if pr:score+=800000+pr*10000
        if self.killers.get(ply)==m:score+=500000
        score+=self.history.get((p.side,a,z),0)
        if fl&1:score+=100
        return score
    def qsearch(self,p,alpha,beta,ply):
        self.tick();checked=attacked(p.b,king_square(p,p.side),p.side^1);allmoves=legal(p)
        if not allmoves:return -MATE+ply if checked else 0
        if p.half>=100:return 0
        if ply>=10:return evaluate(p)
        if not checked:
            stand=evaluate(p)
            if stand>=beta:return stand
            if stand>alpha:alpha=stand
            moves=legal(p,True)
        else:moves=allmoves
        moves.sort(key=lambda m:self.order_score(p,m,-1,ply),reverse=True)
        for m in moves:
            value=-self.qsearch(make(p,m),-beta,-alpha,ply+1)
            if value>=beta:return value
            if value>alpha:alpha=value
        return alpha
    def search(self,p,depth,alpha,beta,ply):
        self.tick()
        if depth<=0:return self.qsearch(p,alpha,beta,ply)
        if p.half>=100:return 0
        key=(p.b,p.side,p.rights,p.ep,min(p.half,100));orig=alpha;oldbeta=beta
        ent=self.tt.get(key);ttmove=-1
        if ent is not None:
            td,val,flag,ttmove=ent
            if td>=depth:
                if flag==0:return val
                if flag==1:alpha=max(alpha,val)
                else:beta=min(beta,val)
                if alpha>=beta:return val
        moves=legal(p)
        if not moves:return -MATE+ply if attacked(p.b,king_square(p,p.side),p.side^1) else 0
        moves.sort(key=lambda m:self.order_score(p,m,ttmove,ply),reverse=True)
        best=-INF;bestmove=moves[0]
        for m in moves:
            q=make(p,m);nextdepth=depth-1
            if attacked(q.b,king_square(q,q.side),q.side^1) and depth<=3:nextdepth+=1
            value=-self.search(q,nextdepth,-beta,-alpha,ply+1)
            if value>best:best=value;bestmove=m
            if value>alpha:alpha=value
            if alpha>=beta:
                if p.b[m&63].lower()!='p' and p.b[(m>>6)&63]=='.' and not (m>>12)&15:
                    self.killers[ply]=m
                    h=(p.side,m&63,(m>>6)&63);self.history[h]=min(10000,self.history.get(h,0)+depth*depth)
                break
        flag=2 if best<=orig else 1 if best>=oldbeta else 0
        self.tt[key]=(depth,best,flag,bestmove)
        if len(self.tt)>150000:self.tt.clear()
        return best
    def root(self,p,moves,depth):
        alpha=-INF;best=-INF;bestmove=moves[0]
        moves=sorted(moves,key=lambda m:self.order_score(p,m,-1,0),reverse=True)
        for m in moves:
            self.tick();value=-self.search(make(p,m),depth-1,-INF,-alpha,1)
            if value>best:best=value;bestmove=m
            if value>alpha:alpha=value
        return best,bestmove
    def think(self,millis):
        moves=legal(self.pos)
        if not moves:return '0000'
        fallback=text_move(moves[0])
        if millis<=8:return fallback
        self.nodes=0;self.deadline=time.perf_counter()+max(0.001,millis/1000.0*0.78);best=moves[0]
        for depth in range(1,64):
            try:value,candidate=self.root(self.pos,moves,depth)
            except TimeoutError:break
            best=candidate
            if abs(value)>=MATE-1000:break
        return text_move(best)
    def set_position(self,tok):
        try:
            if len(tok)>1 and tok[1]=='startpos':p=Position.start();i=2
            elif len(tok)>=8 and tok[1]=='fen':p=Position.fen(' '.join(tok[2:8]));i=8
            else:return
            if i<len(tok) and tok[i]=='moves':
                for u in tok[i+1:]:
                    for m in legal(p):
                        if text_move(m)==u:p=make(p,m);break
            self.pos=p;self.tt.clear();self.history.clear();self.killers.clear()
        except (ValueError,IndexError):return

def main():
    e=Engine()
    for line in sys.stdin:
        tok=line.strip().split()
        if not tok:continue
        if tok[0]=='uci':
            print('id name CleanRoomPython');print('id author Codex');print('uciok');sys.stdout.flush()
        elif tok[0]=='isready':
            print('readyok');sys.stdout.flush()
        elif tok[0]=='ucinewgame':
            e.tt.clear();e.history.clear();e.killers.clear()
        elif tok[0]=='position':e.set_position(tok)
        elif tok[0]=='go':
            limit=1000
            if 'movetime' in tok:
                try:limit=max(1,int(tok[tok.index('movetime')+1]))
                except (ValueError,IndexError):pass
            print('bestmove '+e.think(limit));sys.stdout.flush()
        elif tok[0]=='quit':break

if __name__=='__main__':main()
